<script setup lang="ts">
import{ref}from'vue';import Modal from'../ui/Modal.vue';import{backupTrips,normalizeBackup,backupWarnings}from'../../../shared/backup';import{api}from'../app/api';const emit=defineEmits<{close:[];open:[id:string]}>();const warnings=ref<string[]>([]),source=ref<any>(null),trips=ref<any[]>([]),index=ref(0),preview=ref<any>(null),error=ref(''),another=ref(false),busy=ref(false);async function select(e:Event){error.value='';preview.value=null;source.value=null;try{const f=(e.target as HTMLInputElement).files?.[0];if(!f)return;if(f.size>5*1024*1024)throw Error('文件不能超过 5MB');const raw=JSON.parse(await f.text());trips.value=backupTrips(raw);source.value=raw;index.value=0;inspect()}catch(e){error.value=(e as Error).message}}function inspect(){try{preview.value=normalizeBackup(source.value,index.value);warnings.value=backupWarnings(source.value,index.value);error.value=''}catch(e){error.value=(e as Error).message;preview.value=null}}async function submit(){busy.value=true;try{const r=await api('/imports','POST',{backup:source.value,index:index.value,another:another.value});emit('open',r.id)}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script>
<template><Modal title="导入旅行副本" @close="emit('close')"><p class="muted">先在本机预览。确认后才保存到当前工作区，不改动原文件，也不自动邀请旧成员。</p><label>选择 JSON 备份<input type="file" accept="application/json,.json" @change="select"></label><label v-if="trips.length">选择旅行<select v-model.number="index" @change="inspect"><option v-for="(t,i) in trips" :value="i">{{t.title}}</option></select></label><div v-if="preview" class="import-preview"><h3>{{preview.title}}</h3><p>{{preview.startDate}} — {{preview.endDate}}</p><p>{{preview.entities.length}} 条资料 · {{preview.entities.filter((e:any)=>e.kind==='participant').length}} 位业务参与者</p><p class="muted small">将生成新的旅行及记录编号。旧成员名称不会变成登录权限。源字段保留在私有备份中。</p><div v-if="warnings.length" class="notice"><strong>以下资料暂不显示在网页业务界面</strong><ul><li v-for="warning in warnings">{{warning}}</li></ul></div><label class="check-label"><input v-model="another" type="checkbox">即使此前导入过，也另建一份副本</label><button class="primary full" :disabled="busy" @click="submit">确认导入副本</button></div><p v-if="error" class="error" role="alert">{{error}}</p></Modal></template>

